172: function hintContainsSecret(hint,word){
173:  const tokens=value=>String(value).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
174:  const secret=tokens(word),clue=tokens(hint);
175:  if(!secret.length)return false;
176:  return clue.some((_,start)=>secret.every((token,index)=>clue[start+index]===token));
177: }
178: function hintHash(word,category){
179:  let hash=2166136261;
180:  for(const char of `${category}:${word}`){hash^=char.codePointAt(0);hash=Math.imul(hash,16777619)}
181:  return hash>>>0;
182: }
183: function generateHint(word,category){
184:  const rules=HINT_RULES[category];
185:  const key=String(word||'').trim().toLowerCase();
186:  const group=rules?.groups.find(rule=>rule.words.split('|').includes(key));
187:  const dedicated=group?.hints||[];
188:  const fallback=CATEGORY_HINT_FALLBACKS[category]||rules?.fallback||['Think about the setting, purpose, or defining features associated with this kind of thing.'];
189:  const choices=dedicated.filter(hint=>hint&& !hintContainsSecret(hint,word));
190:  const safeChoices=choices.length?choices:fallback.filter(hint=>hint&& !hintContainsSecret(hint,word));
191:  if(!safeChoices.length){
192:   const emergency=['Its context and defining traits may help.','Consider its role and usual setting.','Look at the features, skills, or surroundings involved.','Think about how it is used or experienced.','Its setting and purpose offer a useful starting point.'].filter(hint=>!hintContainsSecret(hint,word));
193:   if(emergency.length)return emergency[hintHash(key,category)%emergency.length];
194:   return ['Look closer.','Explore further.','Consider the context.'].find(hint=>!hintContainsSecret(hint,word))||'Look closer.';
195:  }
196:  return safeChoices[hintHash(key,category)%safeChoices.length];
197: }
