18: function readStore(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value===null?fallback:value}catch{return fallback}}
19: function makeParty(name,players=[]){return{id:`party-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,name,players:[...players],scores:{},stats:{},history:[]}}
20: const savedPlayers=readStore('imposter.players',[...DEFAULT_NAMES]);
21: const savedScores=readStore('imposter.scores',{});
22: const savedSettings=readStore('imposter.settings',{});
23: const storedSettings=Object.fromEntries(Object.entries(savedSettings).filter(([key])=>key!=='typedClues'));
24: const savedParties=readStore('imposter.parties',[]);
25: const hasSavedParties=localStorage.getItem('imposter.parties')!==null;
26: const parties=Array.isArray(savedParties)?savedParties.filter(p=>p&&p.id&&Array.isArray(p.players)).map(p=>({...p,scores:p.scores||{},stats:p.stats||{},history:Array.isArray(p.history)?p.history:[]})):[];
27: if(!parties.length&&!hasSavedParties)parties.push({...makeParty('My Party',savedPlayers),scores:savedScores});
28: const selectedParty=parties.find(p=>p.id===localStorage.getItem('imposter.activeParty'))||parties[0]||null;
