39: function save(){const party=state.parties.find(p=>p.id===state.activePartyId);if(party){party.players=state.players;party.scores=state.scores}localStorage.setItem('imposter.players',JSON.stringify(state.players));localStorage.setItem('imposter.scores',JSON.stringify(state.scores));localStorage.setItem('imposter.settings',JSON.stringify(state.settings));localStorage.setItem('imposter.parties',JSON.stringify(state.parties));if(state.activePartyId)localStorage.setItem('imposter.activeParty',state.activePartyId);else localStorage.removeItem('imposter.activeParty')}
40: function esc(s){ return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
41: function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.classList.remove('show'),2100)}
42: function randomize(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
43: function maxImposters(){return Math.max(0,state.players.length-2)}
44: function recommendedImposters(){return state.players.length<3?0:Math.min(Math.floor((state.players.length-3)/5)+1,maxImposters())}
45: function normalizeImposterCount(){const max=maxImposters();const current=Number(state.settings.imposters);const next=max<1?1:Math.min(max,Math.max(1,Number.isInteger(current)?current:1));if(next===state.settings.imposters)return false;state.settings.imposters=next;return true}
46: function allCategories(){return BASE_CATEGORIES}
47: function wordsFor(category){return(WORDS[category]||'').split(',').map(word=>word.trim()).filter(Boolean)}
48: function chooseWord(categories,usedWords){
49:  const pick=()=>{
50:   const available=categories.map(category=>({category,words:[...new Set(wordsFor(category))].filter(word=>!usedWords.includes(word))})).filter(group=>group.words.length);
51:   if(!available.length)return null;
52:   const group=available[Math.floor(Math.random()*available.length)];
53:   return{word:group.words[Math.floor(Math.random()*group.words.length)],category:group.category};
54:  };
55:  let selection=pick();if(!selection){usedWords.length=0;selection=pick()}return selection;
56: }
